package ar.edu.utn.frc.tup.piv.llm.api; import ar.edu.utn.frc.tup.piv.llm.application.CalibrationRunService; import ar.edu.utn.frc.tup.piv.llm.infrastructure.persistence.CalibrationRunRepository.Run; import ar.edu.utn.frc.tup.piv.llm.infrastructure.persistence.ProviderCredentialRepository; import ar.edu.utn.frc.tup.piv.llm.security.*; import java.util.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/llm/courses/{courseId}/calibrations") public class CalibrationRunController {private final CalibrationRunService s;private final GoldenSetAuthorization a;private final CourseAuthorization c;private final ProviderCredentialRepository models;@Autowired public CalibrationRunController(CalibrationRunService s,GoldenSetAuthorization a,CourseAuthorization c,ProviderCredentialRepository models){this.s=s;this.a=a;this.c=c;this.models=models;}public CalibrationRunController(CalibrationRunService s,GoldenSetAuthorization a,CourseAuthorization c){this(s,a,c,null);}@GetMapping public CalibrationPage list(@PathVariable UUID courseId,@RequestHeader HttpHeaders h){auth(courseId,h);return new CalibrationPage(s.list(courseId));}@PostMapping public ResponseEntity<Run> create(@PathVariable UUID courseId,@RequestBody Request r,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader HttpHeaders h){var x=auth(courseId,h);UUID target=models==null?r.modelDeploymentId():models.calibrationTarget().map(ProviderCredentialRepository.Deployment::id).orElseThrow(()->new IllegalStateException("El admin debe seleccionar un modelo candidato para calibrar"));return ResponseEntity.accepted().body(s.enqueue(courseId,r.rubricVersionId(),r.goldenSetVersionId(),target,key,x));}@GetMapping("/{runId}")public Run get(@PathVariable UUID courseId,@PathVariable UUID runId,@RequestHeader HttpHeaders h){auth(courseId,h);return s.get(courseId,runId);}private CallerIdentity auth(UUID id,HttpHeaders h){var x=a.require(h);c.requireTeacher(id,x,h);return x;}public record Request(UUID rubricVersionId,UUID goldenSetVersionId,UUID modelDeploymentId){}public record CalibrationPage(List<Run> items){}}
